        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Ain't no reason for me to kill nobody in the ring, unless they deserve it.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I never thought of losing, but now that it's happened, the only thing is to do it right. That's my obligation to all the people who believe in me. We all have to take defeats in life.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "The man who views the world at 50 the same as he did at 20 has wasted 30 years of his life.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I hated every minute of it. But I said to myself, 'Suffer now, and live the rest of your life as a champion'.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Age is whatever you think it is. You are as old as you think you are.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "If Ali says a mosquito can pull a plow, don't ask how. Hitch him up.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Religions all have different names, but they all contain the same truths. … I think the people of our religion should be tolerant and understand people believe different things.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "What's really hurting me, the name Islam is involved, and Muslim is involved and causing trouble and starting hate and violence. … Islam is not a killer religion. … Islam means peace, I couldn't just sit home and watch people label Muslims as the reason for this problem.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I'm retiring because there are more pleasant things to do than beat up people.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "It's a lack of faith that makes people afraid of meeting challenges, and I believe in myself.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "It's just a job. Grass grows, birds fly, waves pound the sand. I beat people up.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I'm not the greatest; I'm the double greatest. Not only do I knock 'em out, I pick the round", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Allah is the Greatest. I'm just the greatest boxer.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I'd like for them to say he took a few cups of love, he took one tablespoon of patience, teaspoon of generosity, one pint of kindness. He took one quart of laughter, one pinch of concern, and then, he mix willingness with happiness, he added lots of faith, and he stired it up well, then he spreads it over his span of a lifetime, and he served it to each and every deserving person he met.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Friendship is a priceless gift that cannot be bought nor sold, but its value is far greater than a mountain made of gold; for gold is cold & lifeless - it can neither see nor hear, in time of trouble its powerless to cheer — it has no ears to listen, no heart to understand, it cannot bring you comfort or reach out a helping hand. So when you ask God for a gift, be﻿ thankful if sends not diamonds, pearls or riches but the love of real true friends.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I believe in Allah and in peace. I don't try to move into white neighborhoods. I don't want to marry a white woman. I was baptized when I was twelve, but I didn't know what I was doing. I'm not a Christian anymore. I know where I'm going and I know the truth, and I don't have to be what you want me to be...I'm free to be what I want.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I am a Muslim and there is nothing Islamic about killing innocent people in Paris, San Bernardino, or anywhere else in the world... True Muslims know that the ruthless violence of so called Islamic Jihadists goes against the very tenets of our religion... We as Muslims have to stand up to those who use Islam to advance their own personal agenda... They have alienated many from learning about Islam. True Muslims know or should know that it goes against our religion to try and force Islam on anybody.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Over the years my religion has changed and my spirituality has evolved. Religion and spirituality are very different, but people often confuse the two. Some things cannot be taught, but they can be awakened in the heart. Spirituality is recognizing the divine light that is within us all. It doesn't belong to any particular religion; it belongs to everyone.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "We all have the same God, we just serve him differently. Rivers, lakes, ponds, streams, oceans all have different names, but they all contain water. So do religions have different names, and they all contain truth, expressed in different ways forms and times. It doesn't matter whether you're a Muslim, a Christian, or a Jew. When you believe in God, you should believe that all people are part of one family. If you love God, you can't love only some of his children.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "My soul has grown over the years, and some of my views have changed. As long as I am alive, I will continue to try to understand more because the work of the heart is never done. All through my life I have been tested. My will has been tested, my courage has been tested, my strength has been tested. Now my patience and endurance are being tested. Every step of the way I believe that God has been with me. And, more than ever, I know that he is with me now. I have learned to live my life one step, one breath, and one moment at a time, but it was a long road. I set out on a journey of love, seeking truth, peace and understanding. l am still learning.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Wouldn't it be a beautiful world if just 10 percent of the people who believe in the power of love would compete with one another to see who could do the most good for the most people? So many of us enjoy taking part in competitions, why not hold a competition of love instead of one that leads to jealousy and envy? If we continue to think and live as if we belong only to different cultures and different religions, with separate missions and goals, we will always be in self-defeating competition with each other.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Once we realize we are all members of humanity, we will want to compete in the spirit of love. In a competition of love we would not be running against one another, but with one another. We would be trying to gain victory for all humanity. If I am a faster runner than you, you may feel bad seeing me pass you in the race, but if you know that we are both racing to make our world better, you will feel good knowing that we are racing toward a common goal, a mutual reward. In a competition of love we'll all share in the victory, no matter who comes first.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Since I won't let the critics seal my fate, they keep hollering I'm full of hate. But they don't really hurt me none, 'cause I'm doing good and having fun.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "My conscience won't let me go shoot my brother, or some darker people, or some poor hungry people in the mud for big powerful America. And shoot them for what? They never called me nigger, they never lynched me, they didn't put no dogs on me, they didn't rob me of my nationality, rape and kill my mother and father. ... Shoot them for what? How can I shoot them poor people? Just take me to jail.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I'm not gonna help nobody get something my negroes don't have. If I'm gonna die, I'll die now right here fighting you, if I'm gonna die. You my enemy. My enemies are white people, not Viet Congs or Chinese or Japanese. You my opposer when I want freedom. You my opposer when I want justice. You my opposer when I want equality. You won't even stand up for me in America for my religious beliefs, and you want me to go somewhere and fight, but you won't even stand up for me here at home.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Why should they ask me to put on a uniform and go 10,000 miles from home and drop bombs and bullets on Brown people in Vietnam while so-called Negro people in Louisville are treated like dogs and denied simple human rights? No I’m not going 10,000 miles from home to help murder and burn another poor nation simply to continue the domination of white slave masters of the darker people the world over. This is the day when such evils must come to an end. I have been warned that to take such a stand would cost me millions of dollars. But I have said it once and I will say it again. The real enemy of my people is here. I will not disgrace my religion, my people or myself by becoming a tool to enslave those who are fighting for their own justice, freedom and equality. If I thought the war was going to bring freedom and equality to 22 million of my people they wouldn’t have to draft me, I’d join tomorrow. I have nothing to lose by standing up for my beliefs. So I’ll go to jail, so what? We’ve been in jail for 400 years.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I knew I had him in the first round. Almighty God was with me. I want everyone to bear witness, I am the greatest! I'm the greatest thing that ever lived. I don't have a mark on my face, and I upset Sonny Liston, and I just turned twenty-two years old. I must be the greatest. I showed the world. I talk to God everyday. I know the real God. I shook up the world, I'm the king of the world. You must listen to me. I am the greatest! I can't be beat!", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I'm the greatest thing that ever lived. I'm so great I don't have a mark on my face. I shook up the world.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "When Cassius says a mouse can outrun a horse, Don't ask how; put your money where your mouse is! I AM THE GREATEST!", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "If you were surprised when Nixon resigned, just watch what happens when I whup Foreman's behind!", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Joe Frazier is so ugly that when he cries, the tears turn around and go down the back of his head.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Frazier is so ugly that he should donate his face to the US Bureau of Wildlife.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "All kinds of things set us back, but life goes on. You don’t shoot yourself. Soon this will be old news. People got lives to live, bills to pay, mouths to feed. Maybe a plane will go down with ninety people on it. Or a great man will be assassinated. That will be more important than Ali losing. I never wanted to lose, never thought I would, but the thing that matters is how you lose. I’m not crying. My friends should not cry.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "There live a great man named Joe who was belittled by a loudmouth foe. While his rival would taunt and tease Joe silently bore the stings. And then fought like gladiator in the ring.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "For every struggle that Joe survived, For every dispute he endured, to rise, Joe will go down in history As a model for champions to come. While Frazier was a man of few words, Ali was a world of mouth, but he found his place in history. Now his heart can express him well. Joe Frazier was a silent warrior, whom Ali silently admired. One could not rise without the other.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "Clay comes out to meet Liston and Liston starts to retreat, if Liston goes back an inch farther he'll end up in a ringside seat. Clay swings with his left, Clay swings with his right, Look at young Cassius carry the fight Liston keeps backing, but there's not enough room, It's a matter of time till Clay lowers the boom. Now Clay lands with a right, what a beautiful swing, And the punch raises the Bear clean out of the ring. Liston is still rising and the ref wears a frown, For he can't start counting till Sonny goes down. Now Liston is disappearing from view, the crowd is going frantic, But radar stations have picked him up, somewhere over the Atlantic. Who would have thought when they came to the fight? That they'd witness the launching of a human satellite. Yes the crowd did not dream, when they put up the money, That they would see a total eclipse of the Sonny.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "This I predict and I know the score, I'll be champ of the world in '64. When I say three, they'll go in the third, So don't bet against me, I'm a man of my word.... He is the greatest! Yes! I am the man this poem's about, I'll be champ of the world, there isn't a doubt. Here I predict Mr. Liston's dismemberment, I'll hit him so hard; he'll wonder where October and November went. When I say two, there's never a third, Bettin' against me is completely absurd.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "You been hearing about how bad I am since you were a little kid with mess in your pants! Tonight, I'm gonna whip you till you cry like a baby.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "That's the only way you gonna save this sucker. He's doomed.", Author = "Muhammad Ali" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Muhammad_Ali", Text = "I predict that when i meet Joe Frazier. This will be like a good amateur fighting a real professional. This will be like a kid out of the Olympics meeting the fastest heavyweight champion who ever lived.", Author = "Muhammad Ali" },
